#   ADMIN_KEY=$(openssl rand -hex 16) PLANS_JSON='...' docker compose up -d
# Put it behind HTTPS (Caddy, nginx, a tunnel) before real use.
services:
  license-keeper:
    build: .
    restart: unless-stopped
    ports: ["8080:8080"]
    volumes: ["state:/data"]
    environment:
      ADMIN_KEY: ${ADMIN_KEY:?set ADMIN_KEY}
      PLANS_JSON: ${PLANS_JSON:?set PLANS_JSON}
      STATE: /data/state.json
      STRIPE_SECRET_KEY: ${STRIPE_SECRET_KEY:-}
      STRIPE_WEBHOOK_SECRET: ${STRIPE_WEBHOOK_SECRET:-}
      COMPANY_NAME: ${COMPANY_NAME:-}
      RESEND_API_KEY: ${RESEND_API_KEY:-}
      MAIL_FROM: ${MAIL_FROM:-}
volumes:
  state:

engine.mjs.text:
// Turns Stripe events into licenses. Idempotent: a replayed event changes nothing.
import { issue, revoke, extend, findBy, claimsOf, DAY } from "./store.mjs";
import { signLicense } from "./token.mjs";

// deps: {plans, stripe, signKey, sendEmail, company, graceDays, now, dryRun}
// plans: {"price_xxx": {product, plan, features, machines, days}}  (days: null = perpetual)
export function licenseEmail(l, token, company = "us") {
  return {
    to: l.email,
    subject: `Your ${l.product} license key`,
    text: `Thanks for buying ${l.product} (${l.plan}).\n\nYour license key:\n\n${token}\n\nPaste it into the app's license screen. It works on up to ${l.machines} machine${l.machines === 1 ? "" : "s"}. Keep this email; the key is how you activate.\n\nIf anything goes wrong, reply to this email.\n\n- ${company}\n`,
  };
}

export async function deliver(state, l, deps) {
  const token = await signLicense(deps.signKey, claimsOf(l));
  const msg = licenseEmail(l, token, deps.company);
  if (deps.dryRun) return `DRY RUN: would email ${l.id} (${l.product}/${l.plan}) to ${l.email}`;
  await deps.sendEmail(msg);
  l.history.push({ at: deps.now, what: "key emailed" });
  return `emailed ${l.id} to ${l.email}`;
}

const grace = (deps) => (deps.graceDays ?? 3) * DAY * 1000;

export async function applyEvent(state, event, deps) {
  if (state.seen[event.id]) return ["duplicate event ignored"];
  state.seen[event.id] = deps.now;
  const ids = Object.keys(state.seen);
  if (ids.length > 5000) for (const k of ids.slice(0, ids.length - 5000)) delete state.seen[k];
  const o = event.data.object;
  const log = [];

  if (event.type === "checkout.session.completed" || event.type === "checkout.session.async_payment_succeeded") {
    if (o.payment_status !== "paid" && o.payment_status !== "no_payment_required") return ["session not paid yet; waiting for async_payment_succeeded"];
    const email = o.customer_details?.email || o.customer_email;
    if (!email) return [`session ${o.id} has no email; issue by hand with POST /v1/licenses`];
    let items;
    try { items = await deps.stripe.lineItems(o.id); } catch (e) { delete state.seen[event.id]; throw e; } // let Stripe retry
    let periodEnd = null;
    if (o.mode === "subscription" && o.subscription) {
      try { periodEnd = (await deps.stripe.subscription(o.subscription)).current_period_end * 1000; } catch (e) { delete state.seen[event.id]; throw e; }
    }
    for (const it of items) {
      const cfg = deps.plans[it.priceId];
      if (!cfg) { log.push(`price ${it.priceId} has no plan in PLANS_JSON; skipped`); continue; }
      const expiresAt = o.mode === "subscription" ? (periodEnd ? periodEnd + grace(deps) : deps.now + 35 * DAY * 1000) : cfg.days ? deps.now + cfg.days * DAY * 1000 : null;
      const l = issue(state, {
        product: cfg.product, email, plan: cfg.plan, features: cfg.features || [], machines: (cfg.machines || 1) * it.quantity, expiresAt,
        stripe: { session: o.id, customer: o.customer || null, subscription: o.subscription || null, paymentIntent: o.payment_intent || null },
      }, deps.now);
      log.push(await deliver(state, l, deps));
    }
    return log.length ? log : ["session had no priced items"];
  }

  if (event.type === "invoice.paid" && o.subscription) {
    const end = Math.max(0, ...(o.lines?.data || []).map((x) => x.period?.end || 0)) * 1000;
    if (!end) return ["invoice had no period; ignored"];
    for (const l of findBy(state, "subscription", o.subscription)) if (extend(state, l.id, end + grace(deps), deps.now)) log.push(`extended ${l.id}`);
    return log.length ? log : ["invoice.paid: nothing to extend"];
  }

  if (event.type === "customer.subscription.deleted") {
    for (const l of findBy(state, "subscription", o.id)) { l.history.push({ at: deps.now, what: "subscription ended; license runs to its paid-through date" }); log.push(`noted end of subscription on ${l.id}`); }
    return log.length ? log : ["no license for this subscription"];
  }

  if (event.type === "charge.refunded" || event.type === "charge.dispute.created") {
    const full = event.type === "charge.dispute.created" || (o.refunded === true);
    if (!full) return ["partial refund: license kept"];
    for (const l of findBy(state, "paymentIntent", o.payment_intent)) { revoke(state, l.id, event.type === "charge.refunded" ? "refunded" : "disputed", deps.now); log.push(`revoked ${l.id}`); }
    return log.length ? log : ["no license for this charge"];
  }

  return [`ignored ${event.type}`];
}

server.mjs.text:
#!/usr/bin/env node
// Self-hosted license-key server for software sold through Stripe. Zero dependencies.
//   STRIPE_SECRET_KEY=rk_... STRIPE_WEBHOOK_SECRET=whsec_... ADMIN_KEY=... \
//   PLANS_JSON='{"price_123":{"product":"myapp","plan":"pro","machines":2,"days":null}}' \
//   RESEND_API_KEY=... MAIL_FROM="Acme <keys@example.com>" COMPANY_NAME=Acme node server.mjs
// DRY_RUN defaults to true: licenses are issued and logged, no email is sent, until DRY_RUN=false.
import http from "node:http";
import fs from "node:fs";
import { timingSafeEqual } from "node:crypto";
import { verifySignature, createStripe } from "./stripe.mjs";
import { applyEvent, deliver } from "./engine.mjs";
import { newState, issue, revoke, activate, deactivate, status, claimsOf, summary } from "./store.mjs";
import { generateKeyPair, signLicense, verifyLicense, parseLicense } from "./token.mjs";

const env = process.env;

const readBody = (req, max = 1_000_000) => new Promise((resolve, reject) => {
  let size = 0; const chunks = [];
  req.on("data", (c) => { size += c.length; if (size > max) { reject(Object.assign(new Error("too large"), { status: 413 })); req.destroy(); } else chunks.push(c); });
  req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
  req.on("error", reject);
});

const bearerOk = (req, key) => {
  const a = Buffer.from(req.headers.authorization || "");
  const b = Buffer.from(`Bearer ${key}`);
  return Boolean(key) && a.length === b.length && timingSafeEqual(a, b);
};

// Fixed-window limiter for the public endpoints (activation is unauthenticated by design).
export function limiter(max = 60, windowMs = 60_000) {
  const hits = new Map();
  return (ip, now) => {
    const w = Math.floor(now / windowMs), h = hits.get(ip);
    if (!h || h.w !== w) { hits.set(ip, { w, n: 1 }); if (hits.size > 10_000) hits.clear(); return true; }
    return ++h.n <= max;
  };
}

// cfg: {state, save, stripe, webhookSecret, adminKey, plans, now, dryRun, sendEmail, company, graceDays, allow}
export function handler(cfg) {
  const now = cfg.now || Date.now;
  const allow = cfg.allow || limiter();
  return async (req, res) => {
    const url = new URL(req.url, "http://x");
    const send = (code, body, type = "application/json") => {
      res.writeHead(code, { "content-type": type, "access-control-allow-origin": "*", "cache-control": "no-store" });
      res.end(typeof body === "string" ? body : JSON.stringify(body, null, 2));
    };
    try {
      if (req.method === "OPTIONS") { res.writeHead(204, { "access-control-allow-origin": "*", "access-control-allow-headers": "content-type,authorization", "access-control-allow-methods": "GET,POST" }); return res.end(); }
      if (url.pathname === "/healthz") return send(200, "ok\n", "text/plain");
      if (req.method === "GET" && url.pathname === "/v1/pubkey") return send(200, { algorithm: "Ed25519", publicKey: cfg.state.keys.publicKey });

      if (req.method === "POST" && url.pathname === "/webhook/stripe") {
        const raw = await readBody(req);
        if (!verifySignature(raw, req.headers["stripe-signature"], cfg.webhookSecret, Math.floor(now() / 1000))) return send(400, "bad signature\n", "text/plain");
        const log = await applyEvent(cfg.state, JSON.parse(raw), { plans: cfg.plans, stripe: cfg.stripe, signKey: cfg.state.keys.privateKey, sendEmail: cfg.sendEmail, company: cfg.company, graceDays: cfg.graceDays, now: now(), dryRun: cfg.dryRun });
        cfg.save();
        log.forEach((l) => console.log(l));
        return send(200, { ok: true, log });
      }

      // Public: the app calls these with its license token and a machine fingerprint.
      if (req.method === "POST" && ["/v1/activate", "/v1/validate", "/v1/deactivate"].includes(url.pathname)) {
        if (!allow(req.socket.remoteAddress || "?", now())) return send(429, { ok: false, reason: "rate-limited" });
        const body = JSON.parse((await readBody(req, 20_000)) || "{}");
        const v = await verifyLicense(cfg.state.keys.publicKey, body.license, { now: now() });
        // An expired token is still a genuine one: activation/validation is how it gets refreshed.
        const parsed = v.valid || v.reason === "expired" ? parseLicense(body.license) : null;
        if (!parsed) return send(400, { ok: false, reason: v.reason });
        const id = parsed.claims.id;
        if (url.pathname === "/v1/deactivate") { const ok = deactivate(cfg.state, id, body.fingerprint, now()); cfg.save(); return send(200, { ok }); }
        const r = url.pathname === "/v1/activate" ? activate(cfg.state, id, body.fingerprint, body.name, now()) : checkOnly(cfg.state, id, body.fingerprint, now());
        cfg.save();
        if (!r.ok) return send(200, { ok: false, reason: r.reason });
        return send(200, { ok: true, token: await signLicense(cfg.state.keys.privateKey, claimsOf(r.license)), expiresAt: r.license.exp ? new Date(r.license.exp * 1000).toISOString() : null });
      }

      if (url.pathname === "/v1/summary" || url.pathname.startsWith("/v1/licenses")) {
        if (!bearerOk(req, cfg.adminKey)) return send(401, "admin key required\n", "text/plain");
        const parts = url.pathname.split("/").filter(Boolean); // v1 licenses [id [revoke|token|resend]]
        if (url.pathname === "/v1/summary") return send(200, { dryRun: cfg.dryRun, ...summary(cfg.state, now()) });
        if (req.method === "GET" && parts.length === 2) return send(200, Object.values(cfg.state.licenses).map((l) => ({ ...l, status: status(l, now()) })));
        if (req.method === "POST" && parts.length === 2) {
          const l = issue(cfg.state, JSON.parse((await readBody(req, 20_000)) || "{}"), now());
          const token = await signLicense(cfg.state.keys.privateKey, claimsOf(l));
          cfg.save();
          return send(201, { id: l.id, token });
        }
        const l = cfg.state.licenses[parts[2]];
        if (!l) return send(404, "no such license\n", "text/plain");
        if (req.method === "GET" && parts[3] === "token") return send(200, { token: await signLicense(cfg.state.keys.privateKey, claimsOf(l)) });
        if (req.method === "POST" && parts[3] === "revoke") { revoke(cfg.state, l.id, "revoked by admin", now()); cfg.save(); return send(200, { ok: true }); }
        if (req.method === "POST" && parts[3] === "resend") { const m = await deliver(cfg.state, l, { signKey: cfg.state.keys.privateKey, sendEmail: cfg.sendEmail, company: cfg.company, now: now(), dryRun: cfg.dryRun }); cfg.save(); return send(200, { ok: true, message: m }); }
      }
      return send(404, "not found\n", "text/plain");
    } catch (e) {
      console.error("request failed:", e.message);
      return send(e instanceof SyntaxError ? 400 : e.status || (/required/.test(e.message) ? 400 : 500), { ok: false, reason: "error" });
    }
  };
}

// validate = activate without consuming a new machine slot.
function checkOnly(state, id, fingerprint, now) {
  const l = state.licenses[id];
  if (!l) return { ok: false, reason: "unknown" };
  const s = status(l, now);
  if (s !== "active") return { ok: false, reason: s };
  if (!l.activations[fingerprint]) return { ok: false, reason: "not-activated" };
  l.activations[fingerprint].lastSeen = now;
  return { ok: true, license: l };
}

function readJson(path, fallback) {
  try { return JSON.parse(fs.readFileSync(path, "utf8")); } catch (e) { if (e.code === "ENOENT") return fallback; throw e; }
}

async function sendResend(msg) {
  const res = await fetch("https://api.resend.com/emails", {
    method: "POST", headers: { authorization: `Bearer ${env.RESEND_API_KEY}`, "content-type": "application/json" },
    body: JSON.stringify({ from: env.MAIL_FROM, to: [msg.to], subject: msg.subject, text: msg.text }),
  });
  if (!res.ok) throw new Error(`resend ${res.status}`);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const missing = ["STRIPE_SECRET_KEY", "STRIPE_WEBHOOK_SECRET", "ADMIN_KEY", "PLANS_JSON"].filter((k) => !env[k]);
  if (missing.length) { console.error(`missing env: ${missing.join(", ")}`); process.exit(1); }
  const dryRun = env.DRY_RUN !== "false";
  if (!dryRun && (!env.RESEND_API_KEY || !env.MAIL_FROM)) { console.error("DRY_RUN=false needs RESEND_API_KEY and MAIL_FROM"); process.exit(1); }
  const statePath = env.STATE || "state.json";
  const state = { ...newState(), ...readJson(statePath, {}) };
  const save = () => { fs.writeFileSync(`${statePath}.tmp`, JSON.stringify(state), { mode: 0o600 }); fs.renameSync(`${statePath}.tmp`, statePath); };
  if (env.SIGNING_PUBLIC_KEY && env.SIGNING_PRIVATE_KEY) state.keys = { publicKey: env.SIGNING_PUBLIC_KEY, privateKey: env.SIGNING_PRIVATE_KEY };
  else if (!state.keys) { state.keys = await generateKeyPair(); save(); console.log("generated a signing key pair; back up STATE, or set SIGNING_PUBLIC_KEY and SIGNING_PRIVATE_KEY"); }
  console.log(`public key (embed in your app): ${state.keys.publicKey}`);
  const cfg = {
    state, save, stripe: createStripe({ key: env.STRIPE_SECRET_KEY }), webhookSecret: env.STRIPE_WEBHOOK_SECRET, adminKey: env.ADMIN_KEY,
    plans: JSON.parse(env.PLANS_JSON), dryRun, sendEmail: sendResend, company: env.COMPANY_NAME, graceDays: env.GRACE_DAYS ? Number(env.GRACE_DAYS) : 3,
  };
  http.createServer(handler(cfg)).listen(Number(env.PORT || 8080), () => console.log(`license-keeper on :${env.PORT || 8080} (${dryRun ? "DRY RUN" : "LIVE"})`));
}

store.mjs.text:
// License state machine. Pure functions over one JSON-serialisable object, no I/O.
import { randomBytes } from "node:crypto";

export const newState = () => ({ licenses: {}, seen: {}, keys: null });

const DAY = 86400;
const sec = (ms) => Math.floor(ms / 1000);
export const newId = () => `lic_${randomBytes(9).toString("base64url")}`;

// plan: {product, plan, features, machines, days (null = perpetual), subscription (bool)}
export function issue(state, { product, email, plan = "standard", features = [], machines = 1, expiresAt = null, stripe = {}, note }, now) {
  if (!product) throw new Error("product required");
  if (!/^[^@\s]+@[^@\s]+$/.test(email || "")) throw new Error("valid email required");
  const id = newId();
  state.licenses[id] = {
    id, product, email: email.toLowerCase(), plan, features, machines: Math.max(1, Number(machines) || 1),
    exp: expiresAt ? sec(expiresAt) : null, iat: sec(now), status: "active", stripe, note: note || null, activations: {}, history: [{ at: now, what: "issued" }],
  };
  return state.licenses[id];
}

export const claimsOf = (l) => ({ id: l.id, product: l.product, email: l.email, plan: l.plan, features: l.features, machines: l.machines, exp: l.exp, iat: l.iat });

export function revoke(state, id, reason, now) {
  const l = state.licenses[id];
  if (!l) return null;
  if (l.status !== "revoked") { l.status = "revoked"; l.history.push({ at: now, what: `revoked: ${reason}` }); }
  return l;
}

// Fixed-term licenses (subscriptions) are extended, never shortened, by a paid renewal.
export function extend(state, id, expiresAt, now) {
  const l = state.licenses[id];
  if (!l || l.status === "revoked" || l.exp === null) return null;
  const exp = sec(expiresAt);
  if (exp > l.exp) { l.exp = exp; l.history.push({ at: now, what: `extended to ${new Date(exp * 1000).toISOString().slice(0, 10)}` }); }
  return l;
}

export const findBy = (state, key, value) => Object.values(state.licenses).filter((l) => l.stripe && l.stripe[key] === value);

export function status(l, now) {
  if (l.status === "revoked") return "revoked";
  if (l.exp !== null && sec(now) >= l.exp) return "expired";
  return "active";
}

// -> {ok, reason, license}. reason: ok | unknown | revoked | expired | machine-limit | bad-fingerprint
export function activate(state, id, fingerprint, name, now) {
  const l = state.licenses[id];
  if (!l) return { ok: false, reason: "unknown" };
  if (!/^[\w.:-]{6,128}$/.test(fingerprint || "")) return { ok: false, reason: "bad-fingerprint" };
  const s = status(l, now);
  if (s !== "active") return { ok: false, reason: s, license: l };
  if (!l.activations[fingerprint]) {
    if (Object.keys(l.activations).length >= l.machines) return { ok: false, reason: "machine-limit", license: l };
    l.activations[fingerprint] = { at: now, name: String(name || "").slice(0, 80) };
    l.history.push({ at: now, what: "activated a machine" });
  }
  l.activations[fingerprint].lastSeen = now;
  return { ok: true, reason: "ok", license: l };
}

export function deactivate(state, id, fingerprint, now) {
  const l = state.licenses[id];
  if (!l || !l.activations[fingerprint]) return false;
  delete l.activations[fingerprint];
  l.history.push({ at: now, what: "deactivated a machine" });
  return true;
}

export function summary(state, now) {
  const by = { active: 0, expired: 0, revoked: 0 };
  let machines = 0;
  for (const l of Object.values(state.licenses)) { by[status(l, now)]++; machines += Object.keys(l.activations).length; }
  return { licenses: Object.keys(state.licenses).length, ...by, machines };
}

export { DAY };

